        stamp(g, ['.SS.', 'SNST', 'SSNT', 'SSST', 'SSTT'], 10, TOP - 5, { S: 'RS', T: 'RT2', N: 'RN' });
        stamp(g, ['.RRRR.', 'RWRRWR', 'RRRRRR', '..SS..', '..SS..'], 58, TOP - 5, { R: 'MR', W: 'MW', S: 'MS' });
